bench( format( '%s:toJSON', pkg ), function benchmark( b ) {
	var values;
	var v;
	var o;
	var i;

	values = [
		'linear',
		'log',
		'sqrt'
	];
	v = new Scale({
		'name': 'xScale'
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.type = values[ i % values.length ];
		o = v.toJSON();
		if ( typeof o !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isPlainObject( o ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
